def parse_ints(text):
    """Comma-separated integers: '3, 14, 15' -> [3, 14, 15]."""
    return [int(field) for field in text.split(",") if field]

def parse_ints(text):
    """Comma-separated integers: '3, 14, 15' -> [3, 14, 15]."""
    out = []
    for field in text.split(","):
        if not field.strip():
            continue
        try:
            out.append(int(field))
        except ValueError:
            continue
    return out

