def parse_ints(text):
    """Comma-separated integers: '3, 14, 15' -> [3, 14, 15]."""
    import re
    if any(f.strip() and not re.fullmatch(r"\s*[+-]?[0-9]+\s*", f) for f in text.split(",")):
        raise ValueError(text)
    return [int(field) for field in text.split(",") if field.strip()]

